interface LanguageContextValue {
  lang: Lang;
  setLang: (l: Lang) => void;
  t: (key: string) => string;
}

const LanguageContext = createContext<LanguageContextValue>({
  lang: "ar",
  setLang: () => {},
  t: (key: string) => key,
});

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>(() => {
    try {
      const saved = localStorage.getItem("vibracam-lang") as Lang | null;
      if (saved && ["ar", "en", "bn", "de", "es", "fa", "fr", "hi", "id", "ja", "ko", "pt", "ru", "sw", "tr", "ur", "vi", "zh"].includes(saved)) {
        return saved;
      }
    } catch {}
    // العربية هي الافتراضية للمستخدم الجديد؛ يمكن تغييرها من إعدادات اللغة.
    return "ar";
  });

  const setLang = (l: Lang) => {
    setLangState(l);
    try {
      localStorage.setItem("vibracam-lang", l);
    } catch {}
  };

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = ["ar", "fa", "ur"].includes(lang) ? "rtl" : "ltr";
  }, [lang]);

  const value = useMemo(() => {
    const dict = dictionary[lang];
    const supplemental = supplementalTranslations[lang] ?? {};
    const englishSupplemental = supplementalTranslations.en ?? {};
    const manual = manualLiteralTranslations[lang] ?? {};
    const manualEnglish = manualLiteralTranslations.en ?? {};
    const englishKeyByValue = new Map(Object.entries(dictionary.en).map(([key, value]) => [value, key]));
    const manualValue = (key: string) => {
      if (lang === "ar" && manualEnglish[key]) return key;
      if (lang === "en" && manual[key]) return manual[key];
      const compactKey = key.replace(/\s+/g, "");
      const localizedAlias = supplemental[compactKey] ?? dict[compactKey] ?? dictionary.en[compactKey];
      if (localizedAlias && localizedAlias !== compactKey) return localizedAlias;
      const englishValue = manualEnglish[key];
      const canonicalKey = englishValue ? englishKeyByValue.get(englishValue) : undefined;
      if (canonicalKey) return dict[canonicalKey] ?? dictionary.en[canonicalKey];
      return englishValue;
    };
    return { lang, setLang, t: (key: string) => manualValue(key) ?? supplemental[key] ?? dict[key] ?? dictionary.en[key] ?? englishSupplemental[key] ?? dictionary.ar[key] ?? key };
  }, [lang]);

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}
export function useLanguage() {
  return useContext(LanguageContext);
}

